9	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
10	
11	interface Frame {
12	  type: string;
13	  sessionId?: string;
14	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
15	  code?: string;
16	  message?: string;
17	}
