21	beforeEach(() => {
22	  logLines.length = 0;
23	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
24	    void logLines.push({level, category, message, fields});
25	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
26	});
27	
28	afterEach(async () => {
29	  await stopEngines();
30	  setLogger();
31	});
32	
33	const startEngine = async (store: SessionStore, userId: string | number = 'u1'): Promise<string> => {
34	  const hal = createServer({
35	    app: (() => undefined) as unknown as Express,
36	    wsAuth: async () => ({id: userId}),
37	    sessionStore: store,
38	    orchestrator: answeringOrchestrator,
39	  });
40	  await hal.start(0);
41	  trackEngine(hal);
42	  const {port} = hal.server.address() as AddressInfo;
43	  return `ws://127.0.0.1:${port}/hal/ws`;
44	};
45	
46	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
47	  const client = connectClient(url);
48	  const frames: Frame[] = [];
49	  let connected: Frame = {type: ''};
50	  await new Promise<void>(resolve => {
51	    // A ping sent on connect is a barrier: its pong can only follow every frame the list answered with.
52	    const onFrame = (frame: Frame): void => {
53	      if (frame.type === 'pong') {
54	        resolve();
55	        return;
56	      }
57	      if (frame.type !== 'connected') {
58	        frames.push(frame);
59	        return;
60	      }
61	      connected = frame;
62	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
63	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
64	    };
65	    client.on('message', raw => onFrame(JSON.parse(String(raw)) as Frame));
66	  });
67	  return {connected, frames};
68	};
69	
70	describe('listing conversations over the WebSocket protocol', () => {
71	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
72	    const inner = new InMemorySessionStore();
73	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
74	    const summaries: SessionSummary[] = [
75	      {
