      entries: ['user A', 'assistant answer 0', 'user B', 'assistant answer 1'],
      frames: [
        'upsert 0 user "A"',
        'upsert 1 assistant ""',
        'delta 1 "answer 0"',
        'commit 1',
        'stream_end',
        'upsert 2 user "B"',
        'upsert 3 assistant ""',
        'delta 3 "answer 1"',
